#include <print>

int main() {
    int score = 100;

    if (score >= 60) {
        std::println("{} 分，及格，恭喜！", score);
    }
    if (score == 100) {
        std::println("满分！");
    }
    if (score = 100) {
        std::println("又进了一次满分！");   // 只有一条警告，这段每次都执行
    }

    std::println("程序照常走到最后一行");
    return 0;
}

